import org.jsoup.select.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen0Test {















    @Test
    public void testHtmlWithMultipleChildrenDifferentTypes() {
        Element element = new Element(Tag.valueOf("ul"), "");
        Element li1 = new Element(Tag.valueOf("li"), "");
        li1.appendText("Item 1");
        Element li2 = new Element(Tag.valueOf("li"), "");
        li2.append("<strong>Item 2</strong>");

        element.appendChild(li1);
        element.appendChild(li2);

        assertEquals("<ul><li>Item 1</li><li><strong>Item 2</strong></li></ul>", element.html());
    }
}
